const words = ["tea", "teapot", "coffee", "cocoa", "toast"];

function fakeSearch(text, signal) {
  return new Promise((resolve, reject) => {
    const t = setTimeout(() => resolve(words.filter(w => w.startsWith(text))), 50 + Math.random() * 250);
    signal.addEventListener("abort", () => { clearTimeout(t); reject(signal.reason); }, { once: true });
  });
}

